mapper.select:
select count(1)
from xitong_yonghu
where denglu_zhanghao = #{dengluZhanghao}

    and id != #{excludeId}

mapper.insert:
insert into xitong_yonghu (
    denglu_zhanghao, mima, xingming, xingbie, shouji, youxiang, touxiang, zhuangtai
) values (
    #{dengluZhanghao}, #{mima}, #{xingming}, #{xingbie}, #{shouji}, #{youxiang},
    coalesce(#{touxiang}, '/uploads/avatar/user-default.jpg'), #{zhuangtai}
)

mapper.update:
update xitong_yonghu
set zhuangtai = #{zhuangtai}
where id = #{id}

update xitong_yonghu
set mima = #{mima}
where id = #{id}

